// Demonstrates: derived queries, safe parameterized JPQL, native SQL with window functions, CTE
package com.bank.sipreport.repository;

import com.bank.sipreport.model.SipInvestment;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.math.BigDecimal;
import java.util.List;

public interface SipReportRepository extends JpaRepository<SipInvestment, String> {

    // Derived query: Spring generates safe, parameterized SQL from the method name.
    // Example call: repo.findByAccountIdAndStatus("SAV2001", "ACTIVE")
    List<SipInvestment> findByAccountIdAndStatus(String accountId, String status);

    // Parameterized JPQL aggregate — ':accountId' is bound, so NO SQL injection.
    // Example call: repo.sumCurrentValueByAccount("SAV2001") returns Rs.163500.00
    @Query("SELECT SUM(s.currentValue) FROM SipInvestment s WHERE s.accountId = :accountId AND s.status = 'ACTIVE'")
    BigDecimal sumCurrentValueByAccount(@Param("accountId") String accountId);

    // NATIVE SQL window function — ranks each account's SIPs best-to-worst by return.
    // ROW_NUMBER() keeps every row while numbering within the account partition.
    // Example call: repo.findSipsRankedByReturn("SAV2001")
    @Query(value = """
        SELECT s.sip_id, s.fund_name,
            ROUND((s.current_value - s.total_invested) / NULLIF(s.total_invested, 0) * 100, 2) AS return_pct,
            ROW_NUMBER() OVER (PARTITION BY s.account_id ORDER BY
                (s.current_value - s.total_invested) / NULLIF(s.total_invested, 0) DESC) AS rank_in_account
        FROM sip_investments s
        WHERE s.account_id = :accountId AND s.status = 'ACTIVE'
        """, nativeQuery = true)
    List<Object[]> findSipsRankedByReturn(@Param("accountId") String accountId);

    // CTE + window functions — monthly trend with running cumulative total and prior-month value.
    // Example call: repo.getMonthlyTrend("SAV2001")
    @Query(value = """
        WITH monthly AS (
            SELECT
                DATE_TRUNC('month', t.txn_date) AS month,
                SUM(t.amount) AS total_amount,
                AVG(t.nav) AS avg_nav
            FROM sip_transactions t
            JOIN sip_investments s ON t.sip_id = s.sip_id
            WHERE s.account_id = :accountId
            GROUP BY DATE_TRUNC('month', t.txn_date)
        )
        SELECT month, total_amount, avg_nav,
            SUM(total_amount) OVER (ORDER BY month) AS cumulative_invested,
            LAG(total_amount) OVER (ORDER BY month) AS prev_month_amount
        FROM monthly
        ORDER BY month
        """, nativeQuery = true)
    List<Object[]> getMonthlyTrend(@Param("accountId") String accountId);
}
