package com.bank.sipreport.service;

import com.bank.sipreport.dto.SipRankRow;
import com.bank.sipreport.dto.SipSummary;
import com.bank.sipreport.model.SipInvestment;
import com.bank.sipreport.repository.SipReportRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class SipReportService {

    private final SipReportRepository sipRepo;

    @Transactional(readOnly = true)
    public SipSummary getAccountSummary(String accountId) {
        log.info("Building SIP summary for account {}", accountId);
        // Uses idx_sip_account_status → index scan, not full table scan
        List<SipInvestment> active = sipRepo.findByAccountIdAndStatus(accountId, "ACTIVE");

        BigDecimal totalCurrentValue = sipRepo.sumCurrentValueByAccount(accountId);
        if (totalCurrentValue == null) totalCurrentValue = BigDecimal.ZERO;

        BigDecimal totalInvested = active.stream()
            .map(SipInvestment::getTotalInvested)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        BigDecimal totalMonthly = active.stream()
            .map(SipInvestment::getMonthlyAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        BigDecimal absoluteReturn = totalCurrentValue.subtract(totalInvested);
        BigDecimal returnPct = totalInvested.compareTo(BigDecimal.ZERO) > 0
            ? absoluteReturn.divide(totalInvested, 4, RoundingMode.HALF_UP).multiply(new BigDecimal("100"))
            : BigDecimal.ZERO;

        return new SipSummary(accountId, active.size(), totalMonthly,
            totalInvested, totalCurrentValue, absoluteReturn, returnPct);
    }

    @Transactional(readOnly = true)
    public List<SipRankRow> getRankedSips(String accountId) {
        return sipRepo.findSipsRankedByReturn(accountId).stream()
            .map(r -> new SipRankRow(
                (String) r[0],
                (String) r[1],
                (BigDecimal) r[2],
                ((Number) r[3]).longValue()))
            .toList();
    }
}
