@RequiredArgsConstructor
public class SipReportController {

    private final SipReportService service;

    @GetMapping("/summary/{accountId}")
    public SipSummary getSummary(@PathVariable String accountId) {
        return service.getAccountSummary(accountId);
    }

    @GetMapping("/ranked/{accountId}")
    public List<SipRankRow> getRanked(@PathVariable String accountId) {
        return service.getRankedSips(accountId);
    }
}
